import{_ as e,o as r,c as o,ag as d}from"./chunks/framework.DJVIMu25.js";const p=JSON.parse('{"title":"Scoring & Events","description":"","frontmatter":{"title":"Scoring & Events"},"headers":[],"relativePath":"en/reference/scoring.md","filePath":"en/reference/scoring.md","lastUpdated":1786545590000}'),a={name:"en/reference/scoring.md"};function n(s,t,i,c,l,h){return r(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="scoring-events" tabindex="-1">Scoring &amp; Events <a class="header-anchor" href="#scoring-events" aria-label="Permalink to &quot;Scoring &amp; Events&quot;">​</a></h1><h2 id="game-scoring-special-events" tabindex="-1">Game Scoring &amp; Special Events <a class="header-anchor" href="#game-scoring-special-events" aria-label="Permalink to &quot;Game Scoring &amp; Special Events&quot;">​</a></h2><p>During a game, each game updates the sidebar scoreboard in real time via <code>onScoreChange</code>, and triggers <code>onGameEvent</code> to award immediate rewards at milestones. Cross-reference to <a href="./../guides/games">Game Modes</a>.</p><table tabindex="0"><thead><tr><th>Game</th><th>Scoring Rule</th><th>Special-Event Reward</th></tr></thead><tbody><tr><td><strong>2048</strong></td><td>Each merge = sum of merged tile values</td><td>Reach 2048 → +50 tokens</td></tr><tr><td><strong>Minesweeper</strong></td><td>+10 per safe cell revealed</td><td>Plays hurt sound on mine hit</td></tr><tr><td><strong>Whack-a-Mole</strong></td><td>+1 per hit, +2 extra on a 3-combo</td><td>Hit a golden mole → +5 tokens</td></tr><tr><td><strong>Bejeweled</strong></td><td>N gems cleared = N×10×chain multiplier</td><td>4+ chain → +N tokens each</td></tr><tr><td><strong>Lottery</strong></td><td>Each draw consumes 1 ticket (or tokens)</td><td>Prize-pool random reward (tokens/coins/commands)</td></tr><tr><td><strong>Slot Machine</strong></td><td>Each spin consumes tokens</td><td>Three-of-a-kind → jackpot pool; two-of-a-kind → fixed tokens</td></tr><tr><td><strong>Maze</strong></td><td>Faster completion = higher score</td><td>Base 30 tokens; -2 per extra 10s (min 5)</td></tr><tr><td><strong>Battleship</strong></td><td>+100 per hit, +500 per sink</td><td>Sink reward = ship size × 5 tokens</td></tr><tr><td><strong>Connect 4</strong></td><td>+1 per drop, +4 on win</td><td>Form a 3-in-a-row threat → +2 tokens</td></tr><tr><td><strong>Tic-Tac-Toe</strong></td><td>+3 win, +1 draw</td><td>Form a 2-in-a-row threat → +1 token</td></tr><tr><td><strong>Rock-Paper-Scissors</strong></td><td>+2 win, +1 draw</td><td>2-streak +2, 3-streak +3 tokens</td></tr><tr><td><strong>Snake</strong></td><td>+10 per food eaten</td><td>Every 50-score milestone → +1 token</td></tr><tr><td><strong>Dino Run</strong></td><td>+1 per alive tick</td><td>Every 50-score milestone → +1 token</td></tr><tr><td><strong>Chess</strong></td><td>Win 200 + capture value×10, Draw 100 + capture value×5</td><td>—</td></tr><tr><td><strong>Monopoly</strong></td><td>Settled by win / draw / lose outcome</td><td>Win +10, Draw +3, Lose +2 tokens (extra reward for correct 3-player bet)</td></tr></tbody></table><h2 id="placeholderapi-placeholders" tabindex="-1">PlaceholderAPI Placeholders <a class="header-anchor" href="#placeholderapi-placeholders" aria-label="Permalink to &quot;PlaceholderAPI Placeholders&quot;">​</a></h2><p>Once PlaceholderAPI is hooked, the following placeholders are available:</p><table tabindex="0"><thead><tr><th>Placeholder</th><th>Description</th></tr></thead><tbody><tr><td><code>%gamebox_tokens%</code></td><td>Current player&#39;s token balance</td></tr><tr><td><code>%gamebox_highscore_&lt;id&gt;%</code></td><td>Current player&#39;s high score in a game (e.g. <code>%gamebox_highscore_2048%</code>)</td></tr><tr><td><code>%gamebox_ingame%</code></td><td>Whether the current player is in a game (true/false)</td></tr></tbody></table>',7)])])}const m=e(a,[["render",n]]);export{p as __pageData,m as default};
